import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Interface: DiscoveryOptions","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/port-mapping/src/discover.ts"},"headers":[],"relativePath":"api/tools/@pumpkin-plugins/port-mapping/discover/interfaces/DiscoveryOptions.md","filePath":"docs/api/tools/@pumpkin-plugins/port-mapping/discover/interfaces/DiscoveryOptions.md","lastUpdated":0}`),a={name:`api/tools/@pumpkin-plugins/port-mapping/discover/interfaces/DiscoveryOptions.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="/pumpkin-plugins/api/tools/@pumpkin-plugins/port-mapping/">@pumpkin-plugins/port-mapping API</a> / <a href="/pumpkin-plugins/api/tools/@pumpkin-plugins/port-mapping/discover/">discover</a> / DiscoveryOptions</p><h1 id="interface-discoveryoptions" tabindex="-1">Interface: DiscoveryOptions <a class="header-anchor" href="#interface-discoveryoptions" aria-label="Permalink to “Interface: DiscoveryOptions”">​</a></h1><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/0356c468512e16f24acef29c775a34d9f3fb4e6e/tools/port-mapping/src/discover.ts#L14" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:14</a></p><p>What to look for and where.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="natpmp" tabindex="-1">natPmp <a class="header-anchor" href="#natpmp" aria-label="Permalink to “natPmp”">​</a></h3><blockquote><p><strong>natPmp</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/0356c468512e16f24acef29c775a34d9f3fb4e6e/tools/port-mapping/src/discover.ts#L16" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:16</a></p><p>Look for NAT-PMP gateways.</p><hr><h3 id="natpmpgateway" tabindex="-1">natPmpGateway? <a class="header-anchor" href="#natpmpgateway" aria-label="Permalink to “natPmpGateway?”">​</a></h3><blockquote><p><code>optional</code> <strong>natPmpGateway?</strong>: <a href="/pumpkin-plugins/api/tools/@pumpkin-plugins/port-mapping/ipv4/interfaces/Endpoint"><code>Endpoint</code></a></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/0356c468512e16f24acef29c775a34d9f3fb4e6e/tools/port-mapping/src/discover.ts#L18" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:18</a></p><p>The NAT-PMP gateway to use. Without it the usual router addresses of the local network are tried.</p><hr><h3 id="screen" tabindex="-1">screen? <a class="header-anchor" href="#screen" aria-label="Permalink to “screen?”">​</a></h3><blockquote><p><code>optional</code> <strong>screen?</strong>: <a href="/pumpkin-plugins/api/tools/@pumpkin-plugins/port-mapping/identify/type-aliases/Screen"><code>Screen</code></a></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/0356c468512e16f24acef29c775a34d9f3fb4e6e/tools/port-mapping/src/discover.ts#L24" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:24</a></p><p>Turns routers down by what they are. It sees every router that gives away its make and model, before anything is asked of it, and a router it gives a reason for is not used: when that leaves no router, discovery throws a <code>RouterRefusedError</code>. Without it routers are not identified.</p><hr><h3 id="searchms" tabindex="-1">searchMs? <a class="header-anchor" href="#searchms" aria-label="Permalink to “searchMs?”">​</a></h3><blockquote><p><code>optional</code> <strong>searchMs?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/0356c468512e16f24acef29c775a34d9f3fb4e6e/tools/port-mapping/src/discover.ts#L26" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:26</a></p><p>How long a UPnP search waits for answers, in milliseconds.</p><hr><h3 id="ssdp" tabindex="-1">ssdp? <a class="header-anchor" href="#ssdp" aria-label="Permalink to “ssdp?”">​</a></h3><blockquote><p><code>optional</code> <strong>ssdp?</strong>: <a href="/pumpkin-plugins/api/tools/@pumpkin-plugins/port-mapping/ipv4/interfaces/Endpoint"><code>Endpoint</code></a></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/0356c468512e16f24acef29c775a34d9f3fb4e6e/tools/port-mapping/src/discover.ts#L28" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:28</a></p><p>Where to send UPnP searches. Defaults to the SSDP multicast group; a router&#39;s own address works when multicast is blocked.</p><hr><h3 id="upnp" tabindex="-1">upnp <a class="header-anchor" href="#upnp" aria-label="Permalink to “upnp”">​</a></h3><blockquote><p><strong>upnp</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/filiphsps/pumpkin-plugins/blob/0356c468512e16f24acef29c775a34d9f3fb4e6e/tools/port-mapping/src/discover.ts#L30" target="_blank" rel="noreferrer">tools/port-mapping/src/discover.ts:30</a></p><p>Look for UPnP gateways.</p>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};